import sys,os
d=sys.argv[1]
css=open(f"{d}/_base.css").read()+".ico{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n"
icons=open(f"{d}/_icons.html").read()
def I(n,c=""): return f'<svg class="ico {c}"><use href="#{n}"/></svg>'
def dots(n,u,cls=""): return f'<div class="dots {cls}">'+"".join(f'<span class="{"p" if i<u else ""}"></span>' for i in range(n))+'</div>'
def frame(cap,body): return f'<div class="frame"><div class="cap">{cap}</div><div class="phone">{body}</div></div>'
def page(title,sub,points,extra_css,frames):
    lis="".join(f"<li>{p}</li>" for p in points)
    return f'''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Assistant:wght@400;600&family=Varela+Round&display=swap" rel="stylesheet">
<style>{css}{extra_css}</style></head><body>{icons}
<div class="intro"><h1>{title}</h1><p>{sub}</p><ul>{lis}</ul></div><div class="frames">{"".join(frames)}</div></body></html>'''

login_field='<label class="f"><span>מייל</span><input class="ltr" value="dana@gmail.com"></label><label class="f"><span>סיסמה</span><input type="password" value="12345678"></label>'
parents=[("דנה כהן","נועה",8,5,True),("מיכל לוי","איתי",10,9,False),("שירה אברהם","",8,2,True),("רוני מזרחי","ליה",5,4,True),("יעל פרץ","עומר",None,0,None)]

