    left=e-u
    rows+=f'<li{" style=\"background:var(--primary-soft);margin:0 -16px;padding:12px 16px\"" if n=="דנה כהן" else ""}><div class="grow"><div><span class="strong">{n}</span>{f"<span class=muted> · {b}</span>" if b else ""}</div>{dots(e,u,"mini")}<div class="row"><span class="faint{" danger-t" if left<=1 else ""}">{left} נותרו</span>{"" if paid else "<span class=\"tag warning\">לא שולם</span>"}</div></div><button class="btn primary">{I("check")}נקב</button></li>'
